def _ensure_notes_dir():
    try:
        os.makedirs(os.path.dirname(CLIENT_NOTES_PATH), exist_ok=True)
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0037', 'suppressed exception excpass_0037', __spina_exc)
        pass

def _load_client_notes():
    """
    Load client notes safely (cached).

    - Primary: <APP_DIR>/data/client_notes.json
    - Fallback (legacy): <CWD>/data/client_notes.json
    - Shallow-merge (primary wins on conflicts)
    - Cached in-memory to avoid frequent disk reads.
    - Logs problems to data/spina_app.log and shows a one-time warning if unreadable/corrupt/too large.
    """
    # Ensure globals exist (only once)
    try:
        if "_NOTES_MAX_BYTES" not in globals():
            globals()["_NOTES_MAX_BYTES"] = 5 * 1024 * 1024  # 5MB
        if "_NOTES_ALERTED" not in globals():
            globals()["_NOTES_ALERTED"] = False
    except Exception as e:
        try:
            _log_exc("notes.init_globals", e)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0038', 'suppressed exception excpass_0038', __spina_exc)
            pass

    global _NOTES_ALERTED, _NOTES_CACHE, _NOTES_CACHE_MTIME

    primary = CLIENT_NOTES_PATH
    fallback = os.path.join(os.getcwd(), "data", "client_notes.json")

    def _warn_once(msg: str):
        global _NOTES_ALERTED
        try:
            if not _NOTES_ALERTED:
                _NOTES_ALERTED = True
                _alert_user("Notes file problem", msg, kind="warning")
        except Exception as e:
            try:
                _log_exc("notes.warn_once", e)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0039', 'suppressed exception excpass_0039', __spina_exc)
                pass

    def _safe_load_one(p: str, label: str) -> dict:
        if not p:
            return {}
        try:
            if not os.path.exists(p):
                return {}
        except Exception as e:
            _log_exc(f"notes.exists({label})", e)
            return {}

        # Size guard (prevent huge JSON from freezing app)
        try:
            max_bytes = int(globals().get("_NOTES_MAX_BYTES", 5 * 1024 * 1024))
            sz = os.path.getsize(p)
            if sz > max_bytes:
                _log_exc(f"notes.too_large({label})", Exception(f"{sz} bytes > {max_bytes} bytes"))
                _warn_once(
                    "Notes file is too large to load safely.\n\n"
                    f"{p}\n\n"
                    f"Size: {sz} bytes\nLimit: {max_bytes} bytes\n\n"
                    "The app will continue without loading notes. Please archive/trim this file."
                )
                return {}
        except Exception as e:
            _log_exc(f"notes.size_check({label})", e)

        try:
            import json as _json2
            with open(p, "r", encoding="utf-8") as f:
                obj = _json2.load(f)
            if isinstance(obj, dict):
                return obj
            _log_exc(f"notes.not_dict({label})", Exception(f"type={type(obj)}"))
            _warn_once(
                "Notes file format looks invalid (expected JSON object).\n\n"
                f"{p}\n\n"
                "The app will continue without loading notes."
            )
            return {}
        except Exception as e:
            # Quarantine corrupt file to avoid repeated failures
            _log_exc(f"notes.load({label})", e)
            try:
                ts = datetime.now().strftime("%Y%m%d_%H%M%S")
                qp = p + f".corrupt_{ts}"
                os.replace(p, qp)
                _warn_once(
                    "Notes file appears unreadable/corrupt and was quarantined.\n\n"
                    f"Original:\n{p}\n\nQuarantined as:\n{qp}\n\n"
                    "The app will continue without loading notes."
                )
            except Exception as e2:
                _log_exc(f"notes.quarantine({label})", e2)
                _warn_once(
                    "Notes file appears unreadable/corrupt.\n\n"
                    f"{p}\n\n"
                    "The app will continue without loading notes. (Could not quarantine the file.)"
                )
            return {}

    # Cached load: if file mtime hasn't changed, return cached dict
    try:
        lock = globals().get("_NOTES_LOCK")
        if lock:
            with lock:
                try:
                    mtime = os.path.getmtime(primary) if os.path.exists(primary) else None
                except Exception:
                    mtime = None
                if isinstance(_NOTES_CACHE, dict) and (_NOTES_CACHE_MTIME == mtime):
                    return _NOTES_CACHE
        else:
            # no lock available
            try:
                mtime = os.path.getmtime(primary) if os.path.exists(primary) else None
            except Exception:
                mtime = None
            if isinstance(_NOTES_CACHE, dict) and (_NOTES_CACHE_MTIME == mtime):
                return _NOTES_CACHE
    except Exception as e:
        _log_exc("notes.cache_check", e)

    notes = {}
    # Load primary + fallback (merge)
    try:
        d_primary = _safe_load_one(primary, "primary")
        d_fallback = _safe_load_one(fallback, "fallback")
        # Merge: fallback first, then primary overwrites
        try:
            if isinstance(d_fallback, dict):
                notes.update(d_fallback)
            if isinstance(d_primary, dict):
                notes.update(d_primary)
        except Exception as e:
            _log_exc("notes.load.merge.update", e)
    except Exception as e:
        _log_exc("notes.load.merge", e)
        notes = {}

    # Update cache
    try:
        lock = globals().get("_NOTES_LOCK")
        if lock:
            with lock:
                _NOTES_CACHE = notes
                try:
                    _NOTES_CACHE_MTIME = os.path.getmtime(primary) if os.path.exists(primary) else None
                except Exception:
                    _NOTES_CACHE_MTIME = None
        else:
            _NOTES_CACHE = notes
            try:
                _NOTES_CACHE_MTIME = os.path.getmtime(primary) if os.path.exists(primary) else None
            except Exception:
                _NOTES_CACHE_MTIME = None
    except Exception as e:
        _log_exc("notes.cache_update", e)
        _NOTES_CACHE = notes
    return notes

def _save_client_notes(notes: dict) -> bool:
    """
    Save client notes atomically and refresh in-memory cache.
    """
    _ensure_notes_dir()
    try:
        import json as _json2
        tmp = CLIENT_NOTES_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _json2.dump(notes, f, ensure_ascii=False, indent=2)
        os.replace(tmp, CLIENT_NOTES_PATH)

        # Refresh cache + mtime
        try:
            lock = globals().get("_NOTES_LOCK")
            if lock:
                with lock:
                    globals()["_NOTES_CACHE"] = notes
                    try:
                        globals()["_NOTES_CACHE_MTIME"] = os.path.getmtime(CLIENT_NOTES_PATH) if os.path.exists(CLIENT_NOTES_PATH) else None
                    except Exception:
                        globals()["_NOTES_CACHE_MTIME"] = None
            else:
                globals()["_NOTES_CACHE"] = notes
                try:
                    globals()["_NOTES_CACHE_MTIME"] = os.path.getmtime(CLIENT_NOTES_PATH) if os.path.exists(CLIENT_NOTES_PATH) else None
                except Exception:
                    globals()["_NOTES_CACHE_MTIME"] = None
        except Exception as e:
            _log_exc("notes.cache_refresh_after_save", e)
        return True
    except Exception as e:
        _log_exc('save_client_notes', e)
        return False

def _migrate_legacy_notes_by_name(
    old_name: str,
    loan_type: str | None = None,
    client_uid: str | None = None,
    person_uid: str | None = None,
) -> bool:
    """Migrate legacy name-based notes (old_name and '<loan_type>::old_name') into stable-id keys.

    Use this when a client's name changes to avoid orphaning notes that were stored under the old name.
    Returns True if any changes were saved.
    """
    try:
        old_name = (old_name or "").strip()
        if not old_name:
            return False

        # Stable targets
        key_shared = _note_id_key("PID", person_uid) or _note_id_key("CID", client_uid)
        key_type = _note_type_key(person_uid, loan_type) or _note_id_key("CID", client_uid)

        if not key_shared and not key_type:
            return False

        notes = _load_client_notes()
        changed = False

        # --- shared legacy keys: old name variants ---
        try:
            legacy_shared = []
            for k in _candidate_note_keys(old_name):
                if k in notes:
                    legacy_shared.append(k)

            if legacy_shared and key_shared:
                # merge into stable shared key (even if it already exists)
                merged = _merge_note_dict(notes.get(key_shared), {})
                for lk in legacy_shared:
                    merged = _merge_note_dict(merged, notes.get(lk))
                if merged:
                    notes[key_shared] = merged
                    changed = True
                for lk in legacy_shared:
                    notes.pop(lk, None)
                    changed = True
        except Exception as e:
            _log_exc("notes:migrate_legacy_shared_by_name", e)

        # --- type legacy keys: '<loan_type>::old name variants' ---
        try:
            prefix = _note_scoped_prefix(loan_type)
            legacy_type = []
            for k in _candidate_note_keys(old_name):
                kk = prefix + k
                if kk in notes:
                    legacy_type.append(kk)

            if legacy_type and key_type:
                merged = _merge_note_dict(notes.get(key_type), {})
                for lk in legacy_type:
                    merged = _merge_note_dict(merged, notes.get(lk))
                if merged:
                    notes[key_type] = merged
                    changed = True
                for lk in legacy_type:
                    notes.pop(lk, None)
                    changed = True
        except Exception as e:
            _log_exc("notes:migrate_legacy_type_by_name", e)

        if changed:
            ok = _save_client_notes(notes)
            return bool(ok)
        return False
    except Exception as e:
        _log_exc("notes:migrate_legacy_by_name", e)
        return False

def _save_collector_notes(self, collector_name, notes_text):
    """Update one collector's notes in collectors.json (atomic, normalized schema)."""
    try:
        collector_name = (collector_name or "").strip()
        if not collector_name:
            return False
        try:
            os.makedirs(DATA_DIR, exist_ok=True)
        except Exception:
            pass
        path = data_path("collectors.json")
        data = _read_json_file(path) or {}

        # Normalize to dict[name] -> {areas:[...], notes:"..."}
        norm = {}

        if isinstance(data, dict):
            for k, v in data.items():
                name = (k or "").strip()
                if not name:
                    continue
                if isinstance(v, dict):
                    areas = v.get("areas", v.get("route", v.get("areas_list", []))) or []
                    notes = v.get("notes", v.get("note", "")) or ""
                elif isinstance(v, list):
                    areas = v
                    notes = ""
                elif isinstance(v, str):
                    areas = []
                    notes = v
                else:
                    areas = []
                    notes = ""
                norm[name] = {"areas": list(areas) if isinstance(areas, (list, tuple)) else [], "notes": str(notes or "")}
        elif isinstance(data, list):
            # Could be list of dicts or list of names
            for item in data:
                if isinstance(item, dict):
                    name = (item.get("name") or item.get("collector") or "").strip()
                    if not name:
                        continue
                    areas = item.get("areas", item.get("route", [])) or []
                    notes = item.get("notes", item.get("note", "")) or ""
                    norm[name] = {"areas": list(areas) if isinstance(areas, (list, tuple)) else [], "notes": str(notes or "")}
                elif isinstance(item, str):
                    name = item.strip()
                    if name:
                        norm[name] = {"areas": [], "notes": ""}
        else:
            norm = {}

        # Preserve existing areas, update notes
        entry = norm.get(collector_name, {"areas": [], "notes": ""})
        areas_keep = entry.get("areas", [])
        norm[collector_name] = {"areas": areas_keep if isinstance(areas_keep, list) else [], "notes": str(notes_text or "").strip()}

        return bool(_write_json_atomic(path, norm))
    except Exception as e:
        try:
            _log_exc("collectors:save_notes", e)
        except Exception:
            pass
        return False

def _save_selected_collector_notes(self):
    """Save Notes from the right panel to collectors.json (atomic)."""
    from tkinter import messagebox
    # Prefer stored selection name, fallback to tree selection
    name = (getattr(self, "_selected_collector_name", "") or "").strip()
    if not name:
        try:
            name = (self._collectors_get_selected_name() or "").strip()
        except Exception:
            name = ""
    if not name:
        messagebox.showwarning("Notes", "Select a collector first.")
        return

    txtw = getattr(self, "collector_route_notes_txt", None)
    notes = ""
    try:
        if txtw:
            notes = (txtw.get("1.0", "end") or "").strip()
    except Exception:
        notes = ""

    ok = False
    try:
        ok = self._save_collector_notes(name, notes)
    except Exception:
        ok = False

    if ok:
        try:
            self.status_var.set(f"Notes saved for '{name}'.")
        except Exception:
            pass
        try:
            self.refresh_collectors()
        except Exception:
            pass
    else:
        messagebox.showwarning("Save Error", "Failed to save notes.\n\nSee log: data/spina_app.log")

def _migrate_legacy_notes_if_needed(self):
    """Move legacy name-based keys into stable-id keys for this client (best-effort).

    This prevents collisions if names repeat, and keeps notes attached even if a name changes.
    Runs only when we have a stable id (person_uid or client_uid).
    """
    # Determine stable targets
    key_shared = _note_id_key("PID", self.person_uid) or _note_id_key("CID", self.client_uid)
    key_type = _note_type_key(self.person_uid, self.loan_type) or _note_id_key("CID", self.client_uid)

    if not key_shared and not key_type:
        return

    notes = _load_client_notes()
    changed = False

    # Shared legacy keys: name variants
    try:
        legacy_shared = []
        for k in _candidate_note_keys(self.client_name):
            if k in notes:
                legacy_shared.append(k)
        if key_shared and key_shared not in notes and legacy_shared:
            # merge legacy entries into stable key
            merged = {}
            for lk in legacy_shared:
                ent = notes.get(lk)
                if isinstance(ent, dict):
                    merged.update(ent)
                elif ent:
                    merged.setdefault("__default__", str(ent).strip())
            if merged:
                notes[key_shared] = merged
                changed = True
            for lk in legacy_shared:
                notes.pop(lk, None)
                changed = True
    except Exception as e:
        _log_exc("notes:migrate_legacy_shared", e)

    # Type legacy keys: '<loan_type>::<name>' variants
    try:
        prefix = _note_scoped_prefix(self.loan_type)
        legacy_type = []
        for k in _candidate_note_keys(self.client_name):
            kk = prefix + k
            if kk in notes:
                legacy_type.append(kk)
        if key_type and key_type not in notes and legacy_type:
            merged = {}
            for lk in legacy_type:
                ent = notes.get(lk)
                if isinstance(ent, dict):
                    merged.update(ent)
                elif ent:
                    merged.setdefault("__default__", str(ent).strip())
            if merged:
                notes[key_type] = merged
                changed = True
            for lk in legacy_type:
                notes.pop(lk, None)
                changed = True
    except Exception as e:
        _log_exc("notes:migrate_legacy_type", e)

    if changed:
        try:
            _save_client_notes(notes)
        except Exception as e:
            _log_exc("notes:migrate_legacy_save", e)

