def _save_collector_notes(self, collector_name, notes_text):
    """Internal: update one collector's notes in collectors.json."""
    try:
        os.makedirs(DATA_DIR, exist_ok=True)
        path = data_path("collectors.json")
        try:
            with open(path, "r", encoding="utf-8") as _f:
                raw = json.load(_f)
        except Exception:
            raw = {}

        data = {}
        if isinstance(raw, dict):
            data = raw
        elif isinstance(raw, list):
            for el in raw:
                if isinstance(el, dict):
                    nm = (el.get("name") or el.get("collector") or "").strip()
                    if not nm:
                        continue
                    aa = el.get("areas") or el.get("route") or []
                    data[nm] = {"areas": aa, "notes": str(el.get("notes") or "")}

        if collector_name not in data:
            data[collector_name] = {"areas": [], "notes": ""}

        rec = data.get(collector_name)
        if not isinstance(rec, dict):
            rec = {"areas": [], "notes": ""}
            data[collector_name] = rec

        rec["notes"] = str(notes_text or "")

        if not _write_json_atomic(path, data):
            raise IOError("atomic write failed")

        self.refresh_collectors()
        try:
            self._populate_collector_details(collector_name)
        except Exception:
            pass
        return True
    except Exception as e:
        _log_exc("collectors:save_notes", e)
        return False

def _toggle_reports_notes_panel():
    try:
        box = getattr(self, 'reports_notes_box', None)
        sep = getattr(self, 'reports_notes_sep', None)
        btn = getattr(self, 'report_notes_btn', None)
        if box is None:
            return
        shown = bool(box.winfo_manager())
        if shown:
            try:
                box.pack_forget()
            except Exception:
                pass
            try:
                if sep is not None:
                    sep.pack_forget()
            except Exception:
                pass
            try:
                if btn is not None:
                    btn.configure(text='Notes…')
            except Exception:
                pass
        else:
            try:
                if sep is not None:
                    sep.pack(fill='x', pady=(8, 6), before=box)
            except Exception:
                try:
                    if sep is not None:
                        sep.pack(fill='x', pady=(8, 6))
                except Exception:
                    pass
            try:
                box.pack(fill='x', pady=(0, 0))
            except Exception:
                pass
            try:
                if btn is not None:
                    btn.configure(text='Hide Notes')
            except Exception:
                pass
            try:
                self._auto_load_report_note()
            except Exception:
                pass
            try:
                self.report_note_txt.focus_set()
            except Exception:
                pass
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_reports_note_toggle_0001', 'suppressed exception excpass_reports_note_toggle_0001', __spina_exc)
        pass

def _toggle_reports_notes_panel():
    try:
        shown = bool(self.reports_notes_box.winfo_manager())
        if shown:
            self.reports_notes_box.pack_forget()
            self.reports_notes_sep.pack_forget()
            self.report_notes_btn.configure(text="Notes")
        else:
            self.reports_notes_sep.pack(fill="x", padx=18, pady=(0, 6))
            self.reports_notes_box.pack(fill="x", padx=18, pady=(0, 18))
            self.report_notes_btn.configure(text="Hide Notes")
            try:
                self._auto_load_report_note()
            except Exception:
                pass
    except Exception:
        pass
